param([string]$ProjectRoot = (Split-Path -Parent $PSScriptRoot))
$ErrorActionPreference = 'Stop'
Add-Type -AssemblyName System.Drawing

# Technical size export only; composition and transparent alpha are generated by ImageGen.
$names = @('welcome_phone', 'listing_under_review', 'no_connection', 'listing_unavailable', 'add_listing_photos')
foreach ($name in $names) {
    $source = [Drawing.Image]::FromFile((Join-Path $ProjectRoot "design/source/illustrations/$name.png"))
    $bitmap = New-Object Drawing.Bitmap(480, 480, ([Drawing.Imaging.PixelFormat]::Format32bppArgb))
    $graphics = [Drawing.Graphics]::FromImage($bitmap)
    try {
        $graphics.Clear([Drawing.Color]::Transparent)
        $graphics.InterpolationMode = [Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
        $graphics.PixelOffsetMode = [Drawing.Drawing2D.PixelOffsetMode]::HighQuality
        $graphics.DrawImage($source, 0, 0, 480, 480)
        $bitmap.Save((Join-Path $ProjectRoot "assets/illustrations/$name.png"), [Drawing.Imaging.ImageFormat]::Png)
    } finally {
        $graphics.Dispose()
        $bitmap.Dispose()
        $source.Dispose()
    }
}

# Opaque onboarding images use JPEG to keep the initial app download small.
$jpegCodec = [Drawing.Imaging.ImageCodecInfo]::GetImageEncoders() | Where-Object MimeType -eq 'image/jpeg'
$jpegParameters = New-Object Drawing.Imaging.EncoderParameters(1)
$jpegParameters.Param[0] = New-Object Drawing.Imaging.EncoderParameter([Drawing.Imaging.Encoder]::Quality, [long]88)
try {
    foreach ($name in @('discover', 'connect', 'publish')) {
        $source = [Drawing.Image]::FromFile((Join-Path $ProjectRoot "design/source/$name.png"))
        $bitmap = New-Object Drawing.Bitmap(900, 900, ([Drawing.Imaging.PixelFormat]::Format24bppRgb))
        $graphics = [Drawing.Graphics]::FromImage($bitmap)
        try {
            $graphics.Clear([Drawing.Color]::FromArgb(250, 247, 242))
            $graphics.InterpolationMode = [Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
            $graphics.PixelOffsetMode = [Drawing.Drawing2D.PixelOffsetMode]::HighQuality
            $graphics.DrawImage($source, 0, 0, 900, 900)
            $bitmap.Save((Join-Path $ProjectRoot "assets/onboarding/$name.jpg"), $jpegCodec, $jpegParameters)
        } finally {
            $graphics.Dispose()
            $bitmap.Dispose()
            $source.Dispose()
        }
    }
} finally {
    $jpegParameters.Dispose()
}
